contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // fuzz: deposit amount and a boolean that decides whether attacker will be used
    function testFuzz_property(uint256 deposit, bool useAttacker) public {
        // keep deposit within reasonable bounds and non-zero for meaningful test
        deposit = bound(deposit, 1 wei, 10 ether);

        // prepare attacker or normal depositor
