        // record prior balance in contract for depositor
        uint256 prior = c.Acc(depositor).balance();

        // perform Put from depositor; attacker will reenter during Put if reentrancy guard removed
        if (useAttacker) {
            // Attacker expects to be msg.sender when Put is called, so prank as attacker
