// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzzed params: amount to deposit, and a flag to choose attacker vs honest actor
    function testFuzz_property(uint256 depositAmount, bool useAttacker) public {
        // keep deposit in reasonable range (but wide)
        depositAmount = bound(depositAmount, 1, 10 ether);

        // deploy an attacker that will reenter on receive and call Collect to try to drain during Put
        ReentrantAttacker attacker = new ReentrantAttacker(address(c));

        address depositor = useAttacker ? address(attacker) : address(0xBEEF);

        // fund depositor
        vm.deal(depositor, depositAmount + 1 ether);

        // ensure attacker has MinSum precondition possibility: fund attacker so Collect can pass MinSum check
        // but we won't put funds into C until deposit

        // perform the call as the depositor
        if (useAttacker) {
            // attacker will attempt to reenter during its Put by having fallback call Collect
            attacker.prepare(depositAmount);
            vm.prank(depositor);
            // call Put with unlock time zero (fallback in contract uses Put(0)); use direct Put call
            c.Put{value: depositAmount}(0);
        } else {
            vm.prank(depositor);
            c.Put{value: depositAmount}(0);
        }

        // SINGLE ASSERT: In the correct contract, after Put completes, Acc[depositor].balance >= depositAmount
        // (i.e., depositor's recorded balance must at least reflect the amount just sent). If reentrancy during
        // Put allowed draining (buggy mutant), attacker can reduce its recorded balance below depositAmount.
        C.Holder memory h = c.Acc(depositor);
        assertTrue(h.balance >= depositAmount);
    }
}

// Minimal attacker that re-enters C during the Put call: its receive() calls back to C.Collect to try to drain.
contract ReentrantAttacker {
    C public target;
    uint public toDeposit;
    bool entered;

    constructor(address _t) {
        target = C(_t);
    }

    function prepare(uint amt) external {
        toDeposit = amt;
        entered = false;
    }

    // when receiving funds during Put, attempt to call Collect to drain some amount
    receive() external payable {
        if (!entered) {
            entered = true;
            // try to pull out half of balance (if any exists) to trigger difference
            uint tryAmt = msg.value / 2;
            // call Collect; ignore failures
            try target.Collect(tryAmt) {} catch {}
        }
    }
}

