pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzz parameters: attacker initial balance, deposit amount, and an arbitrary unlockTime
    function testFuzz_property(uint256 attackerFund, uint256 deposit, uint256 unlockTime) public {
        // keep values in wide but sensible ranges
        vm.assume(deposit <= 10 ether);
        vm.assume(attackerFund >= deposit);
        vm.assume(deposit > 0);
        vm.assume(unlockTime >= 0);

        // deploy a reentrant attacker that will try to call Collect during Put's fallback invocation
        Attacker attacker = new Attacker(address(c));

        // fund attacker externally-owned account that will act as depositor
        address depositor = address(attacker);
        vm.deal(depositor, attackerFund);

        // read prior recorded balance (via public getter Acc)
        C.Holder memory prior = c.Acc(depositor);
        uint256 priorBal = prior.balance;

        // make depositor perform Put by having the attacker contract forward the call
        // attacker will forward by calling c.Put and, if reentrant opportunity exists, try to Collect during execution
        vm.prank(depositor);
        attacker.doPut{value: deposit}(unlockTime);

        // one assertion: after Put completes, recorded balance equals prior + deposit
        C.Holder memory after = c.Acc(depositor);
        assertTrue(after.balance == priorBal + deposit);
    }
}

// adversarial helper: this contract forwards Put to C from its own address (so Acc[msg.sender] is the helper address)
// it tries to exploit missing reentrancy guard by reentering Collect during its payable fallback
contract Attacker {
    C immutable target;
    bool reentered;

    constructor(address _c) {
        target = C(_c);
        reentered = false;
    }

    // caller will fund this contract and then call doPut to forward the Put call
    function doPut(uint256 unlockTime) external payable {
        // forward Put from this contract (so Acc[this] is credited)
        target.Put{value: msg.value}(unlockTime);
    }

    // fallback invoked if target does a call back to this contract (e.g., during logging or external callbacks)
    // try to reenter Collect to drain funds if reentrancy guard missing
    fallback() external payable {
        if (!reentered) {
            reentered = true;
            // attempt to collect the full balance from target for this contract
            // ignore failures (try/catch would be off-chain; use low-level call through target's Collect)
            // here we call target.Collect to trigger any reentrancy exploit when guard is missing
            try target.Collect(address(this).balance) {
                // no-op
            } catch {
                // ignore
            }
        }
    }
}

