pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // fuzzed params: deposit amount and initial attacker balance seed
    function testFuzz_property(uint128 depositAmount, uint64 seed) public {
        // keep deposit non-zero and reasonable to fit within test balance
        uint256 amt = bound(uint256(depositAmount), 1 wei, 5 ether);

        // deploy attacker that will reenter Collect during Put via fallback
        Attacker atk = new Attacker(address(c));

        // fund attacker so it can send amt into Put (and receive Collect payouts)
        vm.deal(address(atk), amt + 1 ether);

        // attacker will call Put on c; during Put's fallback reentrancy point it will call Collect
        // use prank from attacker's address to make msg.sender == attacker
        vm.prank(address(atk));
        // route the call through attacker so C receives from a contract that can reenter
        atk.donate{value: amt}(amt);

        // After Put completes, check the invariant: in the correct contract final recorded balance for attacker
        // must be >= amt (Put should at least credit the sent amount); if nonReentrant_ removed, reentrant Collect
        // during Put can drain funds and make recorded balance < amt for some inputs
        uint256 recorded = c.Acc(address(atk)).balance;

        assertTrue(recorded >= amt);
    }
}

// Minimal attacker that reenters: it calls C.Put(amount) from donate(), and its fallback will call Collect
contract Attacker {
    C c;
    bool reentered;
    constructor(address _c) {
        c = C(_c);
        reentered = false;
    }

    // entry point used by test: calls Put on C from this contract
    function donate(uint256 unlockTime) external payable {
        // call Put with msg.value forwarded
        c.Put{value: msg.value}(unlockTime);
    }

    // fallback called by C when C does a low-level call to msg.sender during Collect; use it to reenter Collect
    fallback() external payable {
        // ensure we only reenter once to simulate draining during Put
        if (!reentered) {
            reentered = true;
            // attempt to drain by calling Collect for some amount: try to take entire balance recorded
            // read recorded balance and call Collect
            uint256 bal = c.Acc(address(this)).balance;
            if (bal > 0) {
                // call Collect to try to withdraw bal
                // ignore failures
                try c.Collect{value: 0}(bal) {
                } catch {
                }
            }
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzz parameters: actor address and unlockTime candidate and deposit amount
    function testFuzz_property(address actor, uint256 suppliedUnlock, uint256 deposit) public {
        // keep deposit reasonable and non-zero
        deposit = bound(deposit, 1 wei, 10 ether);
        // actor should not be zero address
        vm.assume(actor != address(0));

        // fund actor and call Put with suppliedUnlock
        vm.deal(actor, deposit);
        vm.prank(actor);
        c.Put{value: deposit}(suppliedUnlock);

        // Read stored unlockTime from public getter Acc
        (uint256 storedUnlock, uint256 storedBalance) = c.Acc(actor);

        // General rule: reference contract sets acc.unlockTime to max(suppliedUnlock, block.timestamp)
        // Therefore storedUnlock >= suppliedUnlock if suppliedUnlock >= block.timestamp, otherwise storedUnlock >= block.timestamp.
        // We assert the minimal universal fact that storedUnlock >= block.timestamp OR storedUnlock >= suppliedUnlock when suppliedUnlock > block.timestamp.
        // A concise universal assertion: storedUnlock >= block.timestamp || storedUnlock >= suppliedUnlock
        // This will always hold for the reference, but the mutant that forces storedUnlock = block.timestamp can violate it when suppliedUnlock > block.timestamp.

        assertTrue(storedBalance >= deposit);
        assertTrue(storedUnlock >= block.timestamp || storedUnlock >= suppliedUnlock);
    }
}
